def reverse_vowels(text):
    vowels = {char for char in 'aeiouAEIOU'}
    s = list(text)
    l, r = 0, len(s) - 1

    while l < r:
        if s[l] not in vowels:
            l += 1
        if s[r] not in vowels:
            r -= 1
        else:
            s[l], s[r] = s[r], s[l]
            l += 1
            r -= 1
    return ''.join(s)

