def get_ludic(n):
    """
    Returns all lucid numbers smaller than or equal to n.

    A lucid number is defined as a number where the sum of its proper divisors
    minus the number itself equals 0. For example, 6 is a lucid number because its
    proper divisors are 1, 2, and 3, and their sum (1 + 2 + 3) - 6 = 0.

    Parameters:
    n (int): The upper limit to find lucid numbers.

    Returns:
    list: A list containing all lucid numbers less than or equal to n.
    """
    def sum_of_divisors(x):
        """Calculate the sum of proper divisors of a number."""
        divisors = []
        for i in range(1, x):
            if x % i == 0:
                divisors.append(i)
        return sum(divisors)

    lucids = []
    for i in range(1, n + 1):
        if sum_of_divisors(i) - i == 0:
            lucids.append(i)
    return lucids

